SELECT 
FROM exam_paper p
LEFT JOIN `user` u ON p.creator_id = u.id


    AND p.status = #{status}


    AND p.creator_id = #{creatorId}


ORDER BY p.created_at DESC, p.id DESC
LIMIT #{limit} OFFSET #{offset}

